 * @returns {Promise<Response>} 基础模型 API 的响应
 */
async function fetchBaseModel(requestBody) {
  try {
    return await fetch(userConfig.base_LLM_url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${userConfig.base_LLM_authkey}`,
      },
      body: JSON.stringify(requestBody),
    });
  } catch (err) {
    throw new Error("Error contacting base model: " + err.toString());
