/**
 * 处理思考模型的 SSE 响应流，并返回截断后的思考内容
 *
 * 说明:
 *  1. 持续读取 SSE 数据，累计思考文本；
 *  2. 如果 delta 数据中包含 reasoning_content，则优先使用该字段；否则使用 delta.content；
 *  3. 如果传入 controller（用于 SSE 推送），则实时推送数据到客户端；
 *  4. 当检测到截断标记或者思考过程结束时，返回截断后的思考文本。
 *
 * @param {ReadableStreamDefaultReader} reader 思考模型响应流的 Reader 对象
 * @param {ReadableStreamDefaultController|null} [controller=null] SSE 流实时推送 Controller（可选）
 * @returns {Promise<string>} 截断后的思考文本
 */
async function processThinkingStream(reader, controller = null) {
  const decoder = new TextDecoder("utf-8");
  const encoder = new TextEncoder();
  let accumulated = "";
  let buffer = "";
  let isPrevReasoningContent = false;

  while (true) {
    const { value, done } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    // 按 "\ndata: " 分割 SSE 数据块（注意：数据块可能不完整）
    const events = buffer.split("\ndata: ");
    buffer = events.pop() || "";

    for (const event of events) {
      const jsonStart = event.indexOf("{");
      if (jsonStart === -1) continue;

      try {
        const data = JSON.parse(event.slice(jsonStart));
        const deltaObj = data.choices?.[0]?.delta || {};
        let deltaText = "";
        let isThisReasoningContent = false;

        // 判断 delta 对象是否存在 reasoning_content（若存在则使用）
        if (
          Object.prototype.hasOwnProperty.call(deltaObj, "reasoning_content") &&
          deltaObj.reasoning_content !== null
        ) {
          deltaText = deltaObj.reasoning_content;
          isThisReasoningContent = true;
          if (!isPrevReasoningContent && controller) {
            // 推送思考开始标记
            controller.enqueue(encoder.encode(createSSEChunk("\n\n<think>\n")));
          }
        } else {
          deltaText = deltaObj.content || "";
          isThisReasoningContent = false;
        }

        accumulated += deltaText;

        // 判断思考过程是否结束：上一次存在 reasoning_content 而本次没有
        const reasoningEnd = isPrevReasoningContent && !isThisReasoningContent;

        // 如果存在 controller 且思考过程未结束，则实时发送数据
        if (controller && !reasoningEnd) {
          controller.enqueue(encoder.encode(createSSEChunk(deltaText)));
        }

        // 检测到截断标记或者思考过程结束时返回结果
        if (reasoningEnd || accumulated.includes(userConfig.thinking_LLM_truncator)) {
          if (reasoningEnd && controller) {
            controller.enqueue(encoder.encode(createSSEChunk("\n</think>\n\n")));
          }
          const truncIndex = accumulated.indexOf(userConfig.thinking_LLM_truncator);
          if (truncIndex !== -1) {
            return accumulated.slice(0, truncIndex + userConfig.thinking_LLM_truncator.length);
          } else {
            return "<think>" + accumulated + "</think>";
          }
        }
        isPrevReasoningContent = isThisReasoningContent;
      } catch (err) {
        if (userConfig.debug) {
          console.error("Error processing SSE event:", err);
        }
      }
    }
  }
  // 当数据流结束后，如果存在 controller 则推送思考结束标记
  if (controller) {
    controller.enqueue(encoder.encode(createSSEChunk("\n</think>\n\n")));
  }
